{"path": "server.mjs", "content": "// Support ticket MCP server.
//
// Exposes a single tool, `ticket_create`, that creates a support ticket with a
// stable sequential id. Inputs are strictly validated: title and description
// are required non-empty strings, priority is an optional enum
// (low/normal/high, default normal), and no extra fields are permitted.
// Invalid arguments or unknown tool names reject by throwing, which the
// protocol layer turns into a JSON-RPC error response.

const PRIORITIES = ['low', 'normal', 'high'];
const ALLOWED_FIELDS = new Set(['title', 'description', 'priority']);

// Monotonic counter producing stable, sequential ids: t1, t2, t3, ...
let nextTicketId = 0;

const TICKET_CREATE_INPUT_SCHEMA = {
  type: 'object',
  properties: {
    title: {
      type: 'string',
      minLength: 1,
      description: 'Short, non-empty summary of the issue.'
    },
    description: {
      type: 'string',
      minLength: 1,
      description: 'Detailed, non-empty description of the issue.'
    },
    priority: {
      type: 'string',
      enum: PRIORITIES,
      default: 'normal',
      description: 'Ticket priority. One of "low", "normal", or "high". Defaults to "normal".'
    }
  },
  required: ['title', 'description'],
  additionalProperties: false
};

const TOOLS = [
  {
    name: 'ticket_create',
    title: 'Create Support Ticket',
    description:
      'Create a new support ticket with a stable sequential id. ' +
      'Requires a non-empty title and description. ' +
      'Optionally accepts a priority of "low", "normal", or "high" (default "normal"). ' +
      'No other fields are accepted. Returns a concise confirmation including the new ticket id and priority.',
    inputSchema: TICKET_CREATE_INPUT_SCHEMA,
    annotations: {
      readOnlyHint: false,
      destructiveHint: false,
      idempotentHint: false,
      openWorldHint: false
    }
  }
];

function isNonEmptyString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function validateTicketCreate(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object with title, description, and optional priority.');
  }
  for (const key of Object.keys(args)) {
    if (!ALLOWED_FIELDS.has(key)) {
      throw new Error(
        `Unknown field '${key}': ticket_create accepts only title, description, and priority.`
      );
    }
  }
  const title = args.title;
  if (!isNonEmptyString(title)) {
    throw new Error("Invalid argument 'title': must be a non-empty string.");
  }
  const description = args.description;
  if (!isNonEmptyString(description)) {
    throw new Error("Invalid argument 'description': must be a non-empty string.");
  }
  // Default applies only when priority is absent (undefined); an explicit
  // value (including null) must be a valid enum member.
  const priority = args.priority === undefined ? 'normal' : args.priority;
