    throw new Error(
      `Invalid argument 'priority': must be one of low, normal, high (got '${priority}').`
    );
  }
  return { title: title.trim(), description: description.trim(), priority };
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool '${name}'.`);
  }
  const { title, priority } = validateTicketCreate(args);
  const id = 't' + (++nextTicketId);
  const text = `Created ticket ${id}: "${title}" (priority: ${priority})`;
  return {
    content: [{ type: 'text', text }]
  };
}
